CREATE TABLE time_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_profile_id uuid NOT NULL REFERENCES employee_profiles(id), employee_assignment_id uuid REFERENCES employee_assignments(id), started_at timestamptz NOT NULL, ended_at timestamptz NOT NULL, source text NOT NULL, idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (ended_at > started_at), CHECK (source IN ('web', 'mobile', 'manager', 'import')), UNIQUE(employee_profile_id, idempotency_key));
CREATE TABLE time_entry_corrections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), time_entry_id uuid NOT NULL REFERENCES time_entries(id), corrected_started_at timestamptz NOT NULL, corrected_ended_at timestamptz NOT NULL, reason text NOT NULL CHECK (length(trim(reason)) > 0), actor_user_id uuid NOT NULL REFERENCES users(id), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (corrected_ended_at > corrected_started_at), UNIQUE(actor_user_id, idempotency_key));
CREATE INDEX time_entries_employee_started_at_idx ON time_entries (employee_profile_id, started_at DESC);
CREATE INDEX time_entry_corrections_entry_created_at_idx ON time_entry_corrections (time_entry_id, created_at DESC);
CREATE FUNCTION reject_timekeeping_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Timekeeping records are immutable; create a correction instead.'; END; $$;
CREATE TRIGGER time_entries_immutable BEFORE UPDATE OR DELETE ON time_entries FOR EACH ROW EXECUTE FUNCTION reject_timekeeping_mutation();
CREATE TRIGGER time_entry_corrections_immutable BEFORE UPDATE OR DELETE ON time_entry_corrections FOR EACH ROW EXECUTE FUNCTION reject_timekeeping_mutation();
